"""Turn one JUnit file per night into one table: a row per test, a column per night, newest night first."""
import xml.etree.ElementTree as ET
from pathlib import Path

nights = sorted(Path("nights").glob("night-*.xml"), reverse=True)
table: dict[str, dict[str, str]] = {}
for night in nights:
    attempts: dict[str, list[ET.Element]] = {}
    for case in ET.parse(night).iter("testcase"):
        attempts.setdefault(case.get("name"), []).append(case)  # a rerun test has one entry per attempt
    for test, cases in attempts.items():
        last = cases[-1]
        if last.find("failure") is not None or last.find("error") is not None:
            result = "FAIL"
        elif last.find("skipped") is not None:
            result = "quar" if "quarantined" in last.find("skipped").get("message", "") else "skip"
        else:
            result = "rerun" if len(cases) > 1 else "pass"
        table.setdefault(test, {})[night.stem.removeprefix("night-")] = result

columns = [night.stem.removeprefix("night-") for night in nights]
print(f"{'test':22}" + "".join(f"{c:>6}" for c in columns))
for test, row in table.items():
    print(f"{test:22}" + "".join(f"{row.get(c, '-'):>6}" for c in columns))

import pytest


def pytest_configure(config: pytest.Config) -> None:
    config.addinivalue_line("markers", "quarantine(ticket): known flaky; still runs and reports, but cannot turn the night red")


def pytest_collection_modifyitems(items: list[pytest.Item]) -> None:
    for item in items:
        marker = item.get_closest_marker("quarantine")
        if marker is None:
            continue
        ticket = marker.kwargs["ticket"]  # required: every quarantined test has a ticket and an owner
        item.add_marker(pytest.mark.xfail(reason=f"quarantined, see {ticket}", strict=False))

