"""Four integration tests that run once per night. NIGHT says which night it is."""
import os
import random

import pytest

NIGHT = int(os.environ.get("NIGHT", "1"))
attempts: dict[str, int] = {}


def unlucky(name: str, chance: float) -> bool:
    """Whether a timing problem hits this attempt tonight; replaying a night gives the same answer."""
    attempts[name] = attempts.get(name, 0) + 1
    return random.Random(f"{name}-{NIGHT}-{attempts[name]}").random() < chance


def test_list_projects():
    assert ["Lung CT", "Brain MRI"] == ["Lung CT", "Brain MRI"]


def test_archive_project():
    archived = NIGHT < 7  # on night 7 a change was merged that breaks archiving
    assert archived, "archived project still shows in the list"


@pytest.mark.flaky(reruns=2)
def test_upload_scan():
    assert not unlucky("upload_scan", 0.3), "timed out waiting for the scan upload"


def test_run_report():
    assert not unlucky("run_report", 0.35), "report job did not finish in 60 s"
